  id, openid, nickname, avatar_url, bio, role, status, source, created_at, updated_at, last_login_at
) values (#{id}, #{openid}, #{nickname}, #{avatarUrl}, #{bio}, 'user', 'active', #{source}, now(), now(), now())

mapper.update:
update users
set nickname = #{nickname}, avatar_url = #{avatarUrl}, source = #{source}, updated_at = now(), last_login_at = now()
where id = #{id}

